<template><view class="shop-card"><image v-if="image" :src="image" mode="aspectFill"/><view v-else class="shop-placeholder"><ui-icon name="store" :size="46"/></view><view class="copy"><text class="name">{{name}}</text><text class="meta">{{fans}}粉丝</text></view><view v-if="action" :class="['action',{on:active}]" hover-class="tap-active" @tap="$emit('action')">{{active?'已关注':action}}</view></view></template>
<script>export default{emits:['action'],props:{name:{type:String,default:'品奢电竞'},fans:{type:[Number,String],default:0},image:{type:String,default:''},action:{type:String,default:''},active:{type:Boolean,default:false}}}</script>
<style scoped>.shop-card{display:flex;align-items:center;gap:18rpx}.shop-card>image,.shop-placeholder{width:82rpx;height:82rpx;border-radius:16rpx}.shop-placeholder{display:flex;align-items:center;justify-content:center;background:var(--brand-soft)}.copy{min-width:0;flex:1;display:flex;flex-direction:column;gap:8rpx}.name{font-size:27rpx;font-weight:700}.meta{color:var(--muted);font-size:22rpx}.action{padding:13rpx 24rpx;border-radius:30rpx;background:var(--primary);color:#fff;font-size:23rpx}.action.on{background:var(--primary-soft);color:var(--primary)}</style>
